'use strict';
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',devices:'<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',models:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',connect:'<path d="m8 16 8-8M7 14l-2 2a3 3 0 0 0 4 4l3-3M12 7l3-3a3 3 0 0 1 4 4l-2 2"/>',route:'<circle cx="5" cy="6" r="2"/><circle cx="19" cy="18" r="2"/><path d="M7 6h5a5 5 0 0 1 5 5v5M17 18h-5a5 5 0 0 1-5-5V8"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--sidebar)"/><circle cx="15" cy="17" r="3" fill="var(--sidebar)"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 2M5 16a8 8 0 0 1 13 2M5 16a8 8 0 0 0 13 2"/>',export:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',folder:'<path d="M3 6h7l2 2h9v12H3V6Z"/>'};
const svg=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={page:'overview',period:'month',model:'',query:'',offset:0,metric:'cost',device:'',deviceView:'local',data:null,busy:false,dirty:false,providerDraft:null,providerEditorId:null,providerModels:[],providerPresetQuery:'',providerPresetSort:'original',seq:0};
const labels={overview:'总览',providers:'路由',devices:'设备',activity:'用量',models:'价格',sources:'连接',settings:'设置','provider-editor':'路由'};
const ccsPresetPayload=globalThis.CCSwitchCodexPresets||{presets:[]};
const ccsProviderPresets=ccsPresetPayload.presets||[];
const providerTemplates=Object.fromEntries(ccsProviderPresets.map(item=>[item.id,{...item,envKey:'OPENAI_API_KEY'}]));
providerTemplates.codex={...(providerTemplates.codex||{}),name:'OpenAI Official',model:'gpt-5',baseUrl:'https://api.openai.com/v1',envKey:'OPENAI_API_KEY',protocol:'responses',official:true};
providerTemplates.custom={...(providerTemplates.custom||{}),name:'',model:'',baseUrl:'',envKey:'OPENAI_API_KEY',protocol:'responses',category:'custom'};
// These are intentionally recognised by Codex while a user is signed in with
// ChatGPT. The router replaces the selected alias with the provider model.
const codexCompatibleAliases=['gpt-5.6-sol','gpt-5.6-terra','gpt-5.6-luna','gpt-6-astra','gpt-5.5'];
const plans={pro:'Pro',prolite:'Pro Lite',plus:'Plus',free:'Free',team:'Team',business:'Business',edu:'Edu',enterprise:'Enterprise'};
const errors={missing_codex:'未找到 Codex',timeout:'连接超时',unsupported:'当前版本不支持',upstream:'账户查询失败',unavailable:'无法连接',closed:'连接已关闭',process:'无法启动 Codex',no_quota:'未返回额度',login_failed:'登录未完成'};
const locale=()=>LensI18n.resolveLanguage(state.data?.settings.language,navigator.language);
const t=(key,params)=>LensI18n.translate(key,locale(),params);
const helpCopy={
 Tokens:'模型处理的文本单位，包括输入和输出；缓存分类只计算一次。',
 'API 等价成本':'按保存的 API 价格快照换算当前收集用量所得的金额，并非套餐账单或保证节省的费用。',
 缓存读取:'从先前提示缓存中重复使用的输入 Tokens；它们仍属于输入，不会重复计入总量。',
 缓存写入:'供应商写入可重复使用的提示缓存的输入 Tokens。',
 缓存读取占比:'输入 Tokens 中从缓存读取的比例；比例较高通常会降低 API 等价成本。',
 计价覆盖率:'已收集 Tokens 中匹配完整价格规则的比例，不代表账户全部活动都已被收集。',
 未计价:'模型或 Token 分类没有完整价格规则的记录；其 Tokens 仍计入用量。',
 长上下文阈值:'单次请求超过此规模后，模型会采用长上下文价格档位。',
 套餐额度:'Codex 返回的 ChatGPT/Codex 账户级容量，由不同客户端共享，并非单台设备的 Token 总量。',
 模型组合:'根据本机使用习惯、API 等价强度和账户额度速度，为近期模型建议的使用比例。',
 建议可信度:'表示可用价格和额度历史对建议的支持程度，并非结果保证。',
 记录中的估算费用:'根据 Token 数量和价格规则在本地计算的金额，并非供应商报告。',
 来源报告费用:'导入来源记录中自带的金额；Subscription Lens 不将其验证为账单。',
 成功率:'成功请求数除以包含状态码的记录数；没有状态的记录不参与计算。',
 '延迟 P95':'95% 的已测请求在此时间内完成；没有延迟数据的记录不参与计算。',
 多供应商费用:'所选本地来源的估算金额和来源报告金额，统一以 USD 显示，并非账户账单。',
 延迟:'来源提供的请求耗时；缺失值不会按零计算。',
 '首 Token 延迟 P50':'收到第一个输出 Token 所需时间的中位数，仅统计提供该指标的记录。',
 '账户累计 Tokens':'Codex 返回的账户级活动汇总；当前协议不按设备拆分。',
 本机明细:'从这台电脑上已配置的 Codex 目录读取的会话，不会自动包含其他设备。',
 账户汇总:'登录账户返回的聚合活动信息，明细程度低于本机会话记录。',
 '其他设备 / 云端任务明细':'除非单独导入数据，否则无法获取其他电脑或云端任务的详细记录。',
 套餐实付:'本账期实际支付的套餐金额，由用户以 USD 手动填写。',
 额外额度:'本账期额外支付或购买的额度，由用户以 USD 手动填写。',
 费用覆盖倍数:'API 等价成本除以套餐实付金额；它用于比较，并非现金节省。',
 'API 等价强度':'各模型每 Token 对应的已观测 API 等价成本，仅用作相对信号，并非官方套餐额度权重。'
};
const help=(label,key=label)=>{const copy=helpCopy[key];if(!copy)return esc(t(label));const explanation=t(copy),name=t(label);return `<span class="help-term" tabindex="0" data-help="${esc(explanation)}" aria-label="${esc(name+': '+explanation)}">${esc(name)}<span aria-hidden="true">?</span></span>`;};
const decimal=(n,d)=>new Intl.NumberFormat(locale(),{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
const fmt={format:n=>new Intl.NumberFormat(locale()).format(n)};const compact=n=>n===null||n===undefined?'—':n>=1e9?decimal(n/1e9,2)+'B':n>=1e6?decimal(n/1e6,2)+'M':n>=1e3?decimal(n/1e3,1)+'K':fmt.format(n);
const money=n=>n===null||n===undefined?'—':new Intl.NumberFormat(locale(),{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const datetime=s=>s?new Date(s).toLocaleString(locale(),{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const clock=s=>s?new Date(s).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const percentage=(n,d)=>d>0?decimal(n/d*100,1)+'%':'—';
function toast(text){text=t(text);$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function api(name,...args){const r=await window.lens[name](...args);if(!r.ok)throw new Error(r.error);return r.value;}
function filters(){return {period:state.period,model:state.model,query:state.query,device:state.device,offset:state.offset,limit:50};}
let deviceSyncRunning=false,lastDeviceSync=0;
function scheduleDeviceSync(){if(deviceSyncRunning||!state.data?.deviceSync?.configured||Date.now()-lastDeviceSync<300000)return;deviceSyncRunning=true;lastDeviceSync=Date.now();setTimeout(async()=>{try{await api('syncDevices');await load();}catch(error){console.warn('Background device snapshot sync failed:',error?.message||error);}finally{deviceSyncRunning=false;}},1200);}
async function load(){const seq=++state.seq;try{const data=await api('query',filters());if(seq!==state.seq)return;state.data=data;if(!(state.page==='settings'&&state.dirty))render();else updateHeader();scheduleDeviceSync();}catch(e){const message=String(e?.message||e||t("未知错误"));toast(message);if(!state.data)$('#main').innerHTML=`<div class="empty error-state"><p>${t("无法读取数据，请检查日志。")}</p><pre>${esc(message)}</pre></div>`;}}
async function action(fn,success,button){if(button)button.disabled=true;try{const result=await fn();if(result!==null&&success)toast(typeof success==='function'?success(result):success);await load();}catch(e){toast(e.message);}finally{if(button?.isConnected)button.disabled=false;}}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function applyTheme(){const theme=state.data?.settings.theme||'system';document.body.classList.toggle('dark',theme==='dark'||theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.body.classList.toggle('font-large',state.data?.settings.fontScale==='large');document.body.classList.toggle('font-xlarge',state.data?.settings.fontScale==='xlarge');}
function updateHeader(){const d=state.data;$('#update-state').textContent=d?.scanner.running?`${t("读取中 ")}${d.scanner.processed}/${d.scanner.files}`:d?.scanner.lastScan?t("更新于 ")+clock(d.scanner.lastScan):t("未开始监测");}
function periodSelect(){return `<select id="period" aria-label="${t("时间范围")}">${[['today',t("今天")],['week',t("最近 7 天")],['month',t("本月")],['cycle',t("本账期")],['all',t("全部")]].map(([v,n])=>`<option value="${v}" ${state.period===v?'selected':''}>${n}</option>`).join('')}</select>`;}
function head(title,actions='',sub=''){return `<div class="page-head"><div><h1>${title}</h1>${sub?`<div class="page-sub">${sub}</div>`:''}</div><div class="page-actions">${actions}</div></div>`;}
function exportButton(){return `<button class="button" data-action="export">${svg('export')}${t("导出")}</button>`;}
function empty(){return `${head(t("总览"))}<div class="panel onboarding empty"><div class="empty-icon">${svg('folder')}</div><h2>${t("添加 Codex 使用记录")}</h2><p>${t("选择本机的 Codex 目录，开始统计。")}</p><p class="caption">${t("首次连接会回读已有历史记录")}</p><div class="path">${esc(state.data.detectedRoot)}</div><div class="row center"><button class="button primary" data-action="defaultRoot">${t("开始监测")}</button><button class="button" data-action="chooseRoot">${t("选择目录")}</button></div></div>`;}
function chart(){const days=state.data.days;if(!days.length)return `<div class="empty">${t("暂无记录")}</div>`;const cost=state.metric==='cost';const values=days.map(d=>cost?d.usd:d.tokens);const max=Math.max(...values,1)*1.15;const W=680,H=235,L=52,R=12,T=14,B=30,step=(W-L-R)/days.length,bw=Math.min(36,step*.55);let s=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${cost?t("每日 API 等价成本"):t("每日 Token 用量")}">`;for(let i=0;i<4;i++){const y=T+(H-T-B)*i/3,n=max*(3-i)/3;s+=`<line class="grid" x1="${L}" x2="${W-R}" y1="${y}" y2="${y}"/><text x="${L-10}" y="${y+4}" text-anchor="end">${cost?'$'+decimal(n,max>10?0:2):compact(n)}</text>`;}values.forEach((v,i)=>{const h=v/max*(H-T-B),x=L+i*step+(step-bw)/2;s+=`<rect class="bar" x="${x}" y="${H-B-h}" width="${bw}" height="${Math.max(0,h)}" rx="3"><title>${days[i].date} · ${cost?money(v):fmt.format(v)+' tokens'}</title></rect>`;if(i===0||i===values.length-1||i%Math.max(1,Math.ceil(values.length/7))===0)s+=`<text x="${x+bw/2}" y="${H-6}" text-anchor="middle">${new Date(days[i].date+'T12:00:00').toLocaleDateString(locale(),{month:'2-digit',day:'2-digit'})}</text>`;});return s+'</svg>';}
function windowLabel(q){if(q.minutes===null)return t(q.window==='primary'?'短期额度':'长期额度');const days=q.minutes>=1440;return new Intl.NumberFormat(locale(),{style:'unit',unit:days?'day':'hour',unitDisplay:'long',maximumFractionDigits:1}).format(days?Math.round(q.minutes/1440):q.minutes/60);}
function quota(){const d=state.data,q=d.quota;const connected=d.account.state==='connected';const stale=!q||Date.now()-Date.parse(q.observedAt)>300000;return `<section class="panel"><div class="panel-head"><h2>${t("套餐额度")}</h2><span class="pill ${connected&&!stale?'green':''}">${connected&&!stale?t("已连接"):q?t("历史快照"):t("未连接")}</span></div>${q?`<div class="quota-body">${q.windows.map(w=>{const expired=w.resetsAt&&w.resetsAt*1000<Date.now(),remain=Math.max(0,100-w.used);return `<div class="quota"><div class="quota-top"><span>${esc(w.label||w.limit)} · ${windowLabel(w)}</span><strong>${expired?'—':decimal(remain,0)}<small>${expired?'':t("% 剩余")}</small></strong></div><div class="track"><span style="width:${expired?0:remain}%"></span></div><div class="quota-bottom"><span class="${expired?'warning':''}">${expired?t("待刷新"):t("已用 ")+decimal(w.used,0)+'%'}</span><span>${w.resetsAt?t("重置于 {time}").replace("{time}",datetime(w.resetsAt*1000)):t("未提供重置时间")}</span></div></div>`;}).join('')}</div><div class="chart-foot"><span>${q.source==='account'?t("账户接口"):t("本机记录")} · ${datetime(q.observedAt)}</span><button class="text-button" data-page="sources">${t("管理")}</button></div>`:`<div class="empty"><p>${t("连接套餐账户，查看额度。")}</p><button class="button small" data-action="connect">${t("连接账户")}</button></div>`}</section>`;}
function rowsTable(rows){return `<div class="table-wrap"><table><thead><tr><th>${t("时间")}</th><th>${t("项目 / 模型")}</th><th>${help('Tokens')}</th><th>${help('缓存读取')}</th><th>${help('API 等价成本')}</th><th></th></tr></thead><tbody>${rows.length?rows.map(e=>`<tr><td>${datetime(e.at)}</td><td>${esc(e.project)}<div class="sub">${esc(e.model)}</div></td><td>${compact(e.total)}</td><td>${compact(e.cached)}</td><td>${e.price.amount===null?`<span class="pill amber">${help('未计价')}</span>`:money(e.price.usd)}</td><td><button class="text-button" data-detail="${e.id}">${t("详情")}</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${t("暂无记录")}</div></td></tr>`}</tbody></table></div>`;}
function overview(){const d=state.data;if(!d.settings.roots.length)return empty();const s=d.summary,has=s.events>0;return head(t("总览"),periodSelect()+exportButton(),t("本机 · Codex"))+
  `<div class="metrics"><div class="metric"><div class="metric-label">Tokens</div><div class="metric-value">${has?compact(s.tokens):'—'}</div><div class="metric-note">${t("{n} 条记录",{n:s.events})} · ${t("{n} 个会话",{n:s.sessions})}</div></div><div class="metric"><div class="metric-label">${t("API 等价成本")}</div><div class="metric-value">${has?money(s.usd):'—'}</div><div class="metric-note">Standard · USD</div></div><div class="metric"><div class="metric-label">${t("缓存读取占比")}</div><div class="metric-value">${has?percentage(s.cached,s.tokens-s.output):'—'}</div><div class="metric-note">${compact(s.cached)}${t(" 缓存 Tokens")}</div></div><div class="metric"><div class="metric-label">${t("计价覆盖率")}</div><div class="metric-value">${has?percentage(s.pricedTokens,s.tokens):'—'}</div><div class="metric-note">${t("{n} 条未计价",{n:s.unpriced})}</div></div></div>
  <div class="two-col"><section class="panel"><div class="panel-head"><div><h2>${t("用量趋势")}</h2><p>${d.days.length?d.days[0].date+' — '+d.days.at(-1).date:t("暂无记录")}</p></div><div class="segments"><button data-metric="cost" class="${state.metric==='cost'?'active':''}">${t("成本")}</button><button data-metric="tokens" class="${state.metric==='tokens'?'active':''}">Tokens</button></div></div><div class="chart-area">${chart()}</div><div class="chart-foot"><span>${state.metric==='cost'?t("已计价记录"):t("已采集记录")}</span><span>${esc(d.timezone)}</span></div></section>${quota()}</div>
  <div class="bottom-col"><section class="panel"><div class="panel-head"><h2>${t("模型用量")}</h2><button class="text-button" data-page="models">${t("价格")}</button></div><div class="model-bars">${d.models.length?d.models.slice(0,6).map(m=>`<div class="model-row"><div class="model-name"><span>${esc(m.model)}</span><strong>${money(m.usd)} <span class="muted">· ${compact(m.tokens)}</span></strong></div><div class="model-track"><span style="width:${s.tokens?m.tokens/s.tokens*100:0}%"></span></div></div>`).join(''):`<div class="empty">${t("暂无记录")}</div>`}</div></section><section class="panel value-panel"><div class="row" style="justify-content:space-between"><h2>${t("账期对比")}</h2><button class="text-button" data-page="settings">${t("设置")}</button></div><div class="large-number">${s.diff===null?'—':(s.diff>=0?'+':'−')+money(Math.abs(s.diff))}</div><div class="info-row"><span>${t("套餐实付")}</span><strong>${money(d.settings.paid)}</strong></div><div class="info-row"><span>${t("额外额度")}</span><span>${money(d.settings.extra)}</span></div><div class="info-row"><span>${t("费用覆盖倍数")}</span><span>${s.ratio===null?'—':decimal(s.ratio,2)+'×'}</span></div><div class="caption" style="margin-top:15px">${d.settings.paid===null?t("填写账期实付后计算。"):state.period!=='cycle'?t("选择“本账期”查看对比。"):t("API 等价成本减去套餐与额外额度实付。")}</div></section></div>
  <section class="panel"><div class="table-title"><h2>${t("最近记录")}</h2><button class="text-button" data-page="activity">${t("查看全部")}</button></div>${rowsTable(d.rows.slice(0,5))}</section><div class="footnote"><span>${t("价格 ")}${esc(d.catalog.asOf)}${t(" · 按此价格快照估算，不含工具费用")}</span><span>${s.unpriced?t("存在未计价记录"):t("已记录数据")}${t(" · API 等价成本非实际账单")}</span></div>`;}
function activity(){const d=state.data;return head(t("用量"),periodSelect()+exportButton())+`<div class="filters"><input class="input" id="search" aria-label="${t("搜索项目或会话")}" placeholder="${t("搜索项目、模型或会话")}" value="${esc(state.query)}"><select id="model" aria-label="${t("筛选模型")}"><option value="">${t("全部模型")}</option>${d.allModels.map(m=>`<option value="${esc(m)}" ${state.model===m?'selected':''}>${esc(m)}</option>`).join('')}</select><span class="pill">${t("{n} 条记录",{n:d.summary.events})}</span></div><section class="panel">${rowsTable(d.rows)}<div class="pagination"><span>${d.summary.events?d.offset+1:0}–${Math.min(d.offset+d.limit,d.summary.events)} / ${fmt.format(d.summary.events)}</span><div class="row"><button class="button small" data-action="prev" ${!d.offset?'disabled':''}>${t("上一页")}</button><button class="button small" data-action="next" ${d.offset+d.limit>=d.summary.events?'disabled':''}>${t("下一页")}</button></div></div></section>`;}
function devices(){const d=state.data,devices=d.devices||[],c=d.deviceSync||{};return head(t('设备'),`<button class="button" data-action="syncDevices" ${c.configured?'':'disabled'}>${t('立即同步')}</button>`)+`<section class="panel device-sync-panel"><div class="panel-head"><div><h2>${t('Cloudflare R2 同步')}</h2><p>${t('每台设备在指定 bucket 前缀下保存一个 Sublens 统计快照。')}</p></div><span class="pill ${c.configured?'green':''}">${c.configured?t('已配置'):t('未配置')}</span></div><div class="notice">${t('可在此创建专用于 Sublens 的 R2 bucket；也可以填写已有的专用 bucket。对象前缀相当于逻辑文件夹，不会上传源日志、聊天正文、项目路径或凭据。')}</div><form id="device-sync-form"><div class="grid-2"><div class="field"><label for="r2-account">${t('Cloudflare Account ID')}</label><input class="input" id="r2-account" name="accountId" required value="${esc(c.accountId||'')}" autocomplete="off"></div><div class="field"><label for="r2-bucket">${t('R2 bucket')}</label><input class="input" id="r2-bucket" name="bucket" required value="${esc(c.bucket||'')}" autocomplete="off"></div><div class="field"><label for="r2-prefix">${t('对象前缀（逻辑文件夹）')}</label><input class="input" id="r2-prefix" name="prefix" value="${esc(c.prefix||'subscription-lens/devices')}" autocomplete="off"></div><div class="field"><label for="r2-device-name">${t('设备名称')}</label><input class="input" id="r2-device-name" name="deviceName" maxlength="80" required value="${esc(c.deviceName||'')}" autocomplete="off"></div><div class="field"><label for="r2-access">R2 Access Key ID</label><input class="input" id="r2-access" name="accessKeyId" autocomplete="off" placeholder="${c.credentialsSaved?t('已保存；留空以保留'):t('粘贴 Access Key ID')}" value=""></div><div class="field"><label for="r2-secret">R2 Secret Access Key</label><input class="input" id="r2-secret" name="secretAccessKey" type="password" autocomplete="new-password" placeholder="${c.credentialsSaved?t('已保存；留空以保留'):t('粘贴 Secret Access Key')}" value=""></div></div><div class="device-sync-actions"><span class="caption">${t('密钥保存在 Windows 凭据管理器中，不写入统计快照。')}</span><div class="row"><button class="button" type="submit">${t('保存设置')}</button><button class="button" type="button" data-action="createDeviceBucket">${t('创建 R2 bucket')}</button><button class="button" type="button" data-action="testDeviceSync" ${c.configured?'':'disabled'}>${t('测试连接')}</button><button class="button primary" type="button" data-action="syncDevices" ${c.configured?'':'disabled'}>${t('立即双向同步')}</button></div></div></form></section><section class="panel device-list-panel"><div class="panel-head"><div><h2>${t('已同步设备')}</h2><p>${t('每个文件仅包含匿名记录标识、时间、模型、Token 分类和可用计价。')}</p></div><span class="pill">${fmt.format(devices.length)}</span></div><div class="table-wrap"><table><thead><tr><th>${t('设备')}</th><th>Tokens</th><th>${t('API 等价成本')}</th><th>${t('会话')}</th><th>${t('最后同步')}</th><th></th></tr></thead><tbody>${devices.length?devices.map(device=>`<tr><td><strong>${esc(device.label)}</strong>${device.local?` <span class="pill green">${t('本机')}</span>`:''}</td><td>${compact(device.summary.tokens)}</td><td>${money(device.summary.usd)}</td><td>${fmt.format(device.summary.sessions)}</td><td>${datetime(device.lastSync)}</td><td><button class="text-button" data-device="${esc(device.id)}">${t('查看用量')} →</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${t(c.configured?'尚未同步设备；点击“立即双向同步”。':'配置 R2 后，设备会在首次同步时显示在此处。')}</div></td></tr>`}</tbody></table></div></section>`;}
