  if(state.providerPresetSort==='name')presets=[...presets].sort((a,b)=>a.name.localeCompare(b.name));
  const categoryLabels={official:t('官方'),cn_official:t('国内官方'),aggregator:t('聚合服务'),third_party:t('第三方服务'),others:t('其他')};
  const button=item=>`<button type="button" class="ccs-preset-button ${item.id===selected?'selected':''}" data-provider-preset="${esc(item.id)}" title="${esc(categoryLabels[item.category]||categoryLabels.others)}"><span class="ccs-preset-icon" style="--preset-color:${esc(item.iconColor||'#8b8b8b')}">${esc((item.name||'?').slice(0,1).toUpperCase())}</span><span>${esc(item.name)}</span>${item.primePartner?'<b class="ccs-prime">♥</b>':item.partner?'<b class="ccs-partner">★</b>':''}</button>`;
