    const auth=item.authMode==='codex_oauth'?t('CC Switch 已保存的 ChatGPT 授权'):item.credentialSource==='app'?t('应用内密钥已保存'):item.secretConfigured?t('凭据已配置'):t('等待在 CC Switch 中配置');
