const termTip=$('#term-help-tooltip');let activeHelp=null;
function showHelp(target){activeHelp=target;termTip.textContent=target.dataset.help;termTip.hidden=false;termTip.style.left='0px';termTip.style.top='0px';const r=target.getBoundingClientRect(),tip=termTip.getBoundingClientRect(),left=Math.max(12,Math.min(innerWidth-tip.width-12,r.left+r.width/2-tip.width/2)),below=r.bottom+8,top=r.top-tip.height-8;termTip.style.left=left+'px';termTip.style.top=(top>=8?top:Math.min(innerHeight-tip.height-8,below))+'px';}
function hideHelp(target){if(target&&activeHelp!==target)return;activeHelp=null;termTip.hidden=true;}
document.addEventListener('pointerover',event=>{const target=event.target.closest('[data-help]');if(target)showHelp(target);});
